import{aggregator,jsonResolver,padNumber}from"../utils/_utils.js";import{constants}from"../utils/constants/_constants.js";import{getSpesificSurahAyahService}from"./ayah.services.js";import{getSpesificReciterService}from"./reciter.services.js";const generateSurahRecitationAudio=(recitationDir,surahNumber)=>{const paddedNumber=padNumber(surahNumber,3);return`${constants.SERVICE_URL.QURANICAUDIO}${recitationDir}${paddedNumber}.mp3`};const shouldIncludePreBismillah=surahSequence=>surahSequence!==9;const getEntireSurahService=async query=>{const{lang,reciter}=query;const[rawSurah,rawSurahTranslation,preBismillah,spesificReciter]=await Promise.all([jsonResolver("EntireQuranSurah"),jsonResolver(["_translation","lang",lang,"EntireQuranSurahTranslation"]),jsonResolver(["_translation","lang",lang,"PreBismillah"]),getSpesificReciterService(reciter)]);const aggregatedSurah=aggregator(rawSurah,rawSurahTranslation);return aggregatedSurah.map(surah=>({...surah,preBismillah:shouldIncludePreBismillah(surah.sequence)?preBismillah:false,recitation:{audio:generateSurahRecitationAudio(spesificReciter.folder.surah,surah.sequence)}}))};const getSpesificSurahService=async(surahSequence,query)=>{const entireSurah=await getEntireSurahService(query);const selectedSurah=entireSurah.find(surah=>surah.sequence===surahSequence);const spesificSurahAyahs=await getSpesificSurahAyahService(surahSequence,query);return!selectedSurah?null:{...selectedSurah,ayah:spesificSurahAyahs}};export{getEntireSurahService,getSpesificSurahService};